def run_length_encode(s):
    result = []
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i + 1] == s[i]:
            count += 1
            i += 1
        result.append(s[i] + str(count))
        i += 1
    return "".join(result)
