import re

def parse_duration(s):
    pattern = re.compile(r'(\d+)([hms])')
    matches = pattern.findall(s)
    if not matches:
        raise ValueError(f"Invalid duration string: {s}")
    total = 0
    for value, unit in matches:
        value = int(value)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value
    return total
```

